'use strict';
const InventoryControl={
 states:{AVAILABLE:'可用库存',PREPARATION_LOCKED:'备货锁定',LOADING_ASSIGNED:'已分配装车',LOADED_PENDING:'已装车待正式出库',OUTBOUND:'已正式出库'},previewSequence:0,
 warning(d){if(!d)return '';const source=d.limit_source==='DISPATCH'?'派车单车辆载重':d.limit_source==='ADMIN_FALLBACK'?'管理员后备阈值':'未找到该车载重限额';return `<div class="${d.over_limit?'dialog-notice':'lp-load-summary'}" data-weight-warning="${d.over_limit?'OVER_LIMIT':'NORMAL'}"><p>实际装载：<strong>${d.bundle_count}</strong> 捆 · 毛重 <strong>${d.total_gross_weight===null?'未知':Tonnes.format(d.total_gross_weight)}</strong> 吨 · 净重 <strong>${d.total_net_weight===null?'未知':Tonnes.format(d.total_net_weight)}</strong> 吨</p><p>${source}${d.net_limit_tonnes?'：<strong>'+Tonnes.format(d.net_limit_tonnes)+'</strong> 吨':''} · <span data-no-i18n>${esc(d.vehicle_no||'')} · ${esc(d.shipment_month||'')}</span></p>${d.over_limit?'<p><strong>装载净重超过该车预警限额，请核对；此提示不阻断提交或审批。</strong></p>':''}${d.missing_dispatch_capacity?'<p>派车单未提供可匹配的车辆限额，请核对销售计划、发运月份和车头号。</p>':''}</div>`;},
 async preview(doc,ids,existing){const seq=++this.previewSequence,host=$('lp-load-total');if(!host)return;if(!doc){host.textContent='请选择装车计划单';return;}host.textContent='正在核对实际装车数量与重量…';try{const d=await API.request('/v32/loading-weight-preview',{method:'POST',body:{document_id:doc.id,bundle_ids:ids,...(existing?{loading_id:existing.id}:{})}});if(seq===this.previewSequence&&host.isConnected)host.innerHTML=this.warning(d);}catch(e){if(seq===this.previewSequence&&host.isConnected)host.textContent=e.message;}},
 async legacyPreview(lot,ids){const host=$('v26-load-total'),seq=++this.previewSequence;if(!host)return;if(!lot){host.textContent='请选择备货批次';return;}host.textContent='正在核对实际装车数量与重量…';try{const form=$('v26-load'),d=await API.request('/v32/legacy-loading-weight-preview',{method:'POST',body:{allocation_id:lot.id,bundle_ids:ids,vehicle_no:form.elements.vehicle_no.value,load_date:form.elements.load_date.value}});if(seq===this.previewSequence&&host.isConnected)host.innerHTML=this.warning(d);}catch(e){if(seq===this.previewSequence&&host.isConnected)host.textContent=e.message;}},
 async settings(){const d=await API.request('/v32/weight-settings');Router.page('车辆净重预警设置',OutboundCenter.tabs('loads')+`<p>优先使用派车单中与销售计划、发运月份、车头号匹配的车辆载重限额。以下后备阈值仅在未匹配到车辆载重时使用；留空表示不设后备阈值。超限仅提示，不阻断业务。</p><form id="weight-settings" class="user-form"><label>后备净重预警阈值（吨）<input name="fallback_net_tonnes" type="number" min="0.0001" max="1000" step="0.0001" value="${esc(d.fallback_net_tonnes||'')}"></label><label>修改原因<textarea name="reason" required maxlength="1000"></textarea></label><p id="weight-settings-error" class="error" role="alert"></p><button class="button primary">保存设置</button></form>`);$('weight-settings').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=Object.fromEntries(new FormData(e.target));await API.request('/v32/weight-settings',{method:'PATCH',body:{...b,fallback_net_tonnes:b.fallback_net_tonnes||null,version:d.version}});await this.settings();notify('预警设置已保存');}catch(err){$('weight-settings-error').textContent=err.message;e.submitter.disabled=false;}};},
 unmatch(id,d){dialog('解除装车计划单匹配',`<p>将撤销本装车单的车辆分配；仍有效的备货单继续锁定捆包。已装车车辆须先完成实物卸车或受控取消。</p><form id="v32-unmatch" class="user-form"><label>解除原因<textarea name="reason" required minlength="5" maxlength="1000"></textarea></label><p id="v32-unmatch-error" class="error" role="alert"></p><button class="button primary">确认解除匹配</button></form>`);$('v32-unmatch').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await API.request('/v31/loads/'+id,{method:'PATCH',body:{version:d.version,document_id:null,note:e.target.elements.reason.value}});$('dialog').close();await Router.go('/outbounds/loads/'+id);}catch(err){$('v32-unmatch-error').textContent=err.message;e.submitter.disabled=false;}};}
};
const stateSelect=$('business_status');if(stateSelect){const selected=stateSelect.value;stateSelect.innerHTML='<option value="">全部</option>'+Object.values(InventoryControl.states).map(v=>`<option value="${v}">${v}</option>`).join('');stateSelect.value=Object.values(InventoryControl.states).includes(selected)?selected:'';}
StockMap.stateNames.AVAILABLE='可用库存';StockMap.stateNames.LOCKED='备货锁定';StockMap.stateNames.LOADED='已装车待正式出库';
const controlLoad=Flow.load.bind(Flow);Flow.load=async function(id){await controlLoad(id);const d=await API.request('/loads/'+id);if(d.weight_summary)$('page-content').insertAdjacentHTML('afterbegin',InventoryControl.warning(d.weight_summary));if(d.workflow_state==='PENDING'&&Business.can('load:write')){const panel=document.createElement('details');panel.className='lp-load-summary';panel.innerHTML='<summary>撤销未审核装车单</summary><p>撤销后保留历史，解除车辆占用及计划匹配；有效备货单仍保留捆包锁定。</p><form id="v32-cancel" class="user-form"><label>撤销原因<textarea name="reason" required minlength="5" maxlength="500"></textarea></label><p class="error" id="v32-cancel-error" role="alert"></p><button class="button secondary">确认撤销</button></form>';$('page-content').append(panel);$('v32-cancel').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await API.request('/loads/'+id+'/cancel',{method:'POST',body:{version:d.version,reason:e.target.elements.reason.value}});await Router.go('/outbounds/loads/'+id);}catch(err){$('v32-cancel-error').textContent=err.message;e.submitter.disabled=false;}};}};
const controlMatch=LoadingPlans.loadForm.bind(LoadingPlans);LoadingPlans.loadForm=async function(id){await controlMatch(id);if(id&&$('lp-unmatch')){const d=await API.request('/loads/'+id);$('lp-unmatch').onclick=()=>InventoryControl.unmatch(id,d);}};
const controlTabs=OutboundCenter.tabs.bind(OutboundCenter);OutboundCenter.tabs=view=>controlTabs(view)+(Business.can('system:manage')?'<a class="button secondary" href="/outbounds/weight-settings">车辆净重预警设置</a>':'');
const controlRefresh=Dashboard.refresh.bind(Dashboard);Dashboard.refresh=async function(){await controlRefresh();const data=this.snapshot?.workflow;if(!data?.inventory_states)return;$('v32-inventory-states')?.remove();$('dashboard-content').insertAdjacentHTML('afterbegin',`<section id="v32-inventory-states" class="panel"><h2>统一库存业务状态</h2><div class="shipping-kpis">${Object.entries(InventoryControl.states).map(([k,v])=>`<article><span>${v}</span><strong>${data.inventory_states[k]||0}</strong></article>`).join('')}</div><p>备货和装车仅占用库存，生产部经理最终审批正式出库后才扣减账面库存。</p></section>`);};
const controlPermission=Router.permission.bind(Router);Router.permission=p=>p==='/outbounds/weight-settings'?'system:manage':controlPermission(p);
const controlInit=Router.init.bind(Router);Router.init=async function(){this.add(/^\/outbounds\/weight-settings$/,()=>InventoryControl.settings());return controlInit();};

V26.states.CANCELLED='已撤销';

const controlPacking=Shipping.detail.bind(Shipping);Shipping.detail=async function(id){await controlPacking(id);const d=await API.request('/shipping/'+id);if(d.authorized_correction){const p=document.createElement('p');p.className='dialog-notice';p.innerHTML='车辆信息采用已批准更正单：<strong data-no-i18n>'+esc(d.authorized_correction.code)+'</strong> · <span data-no-i18n>'+esc(d.authorized_correction.vehicle_no)+'</span>';$('page-content').prepend(p);}};
